
-- Rollback-only regression; no physical Storage writes.
CREATE TEMP TABLE stage5c_cases(name text PRIMARY KEY) ON COMMIT DROP;
DO $test$
DECLARE b uuid:=gen_random_uuid(); br uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); oldsub uuid:=gen_random_uuid(); sub uuid:=gen_random_uuid();
 b2 uuid:=gen_random_uuid(); rev uuid:=gen_random_uuid(); rev2 uuid:=gen_random_uuid(); rev3 uuid:=gen_random_uuid();
 own text:='qa_5c_owner_'||substr(md5(random()::text),1,17);
 reviewer text:='qa_5c_reviewer_'||substr(md5(random()::text),1,17);
 viewer text:='qa_5c_viewer_'||substr(md5(random()::text),1,17);
 k text; k2 text; img text; oldimg text; refs jsonb; d jsonb; ctx jsonb; listing jsonb;
BEGIN
 INSERT INTO public.users(id,account_status) VALUES(own,'active'),(reviewer,'active'),(viewer,'active');
 INSERT INTO wow_private.admin_members(user_id,role,is_active) VALUES(own,'reviewer',true),(reviewer,'reviewer',true),(viewer,'viewer',true);
 INSERT INTO public.businesses(id,owner_user_id,name,status) VALUES(b,own,'QA verification','pending_review');
 INSERT INTO public.business_members(business_id,user_id,role,status,can_draft,can_submit,can_pause,can_monitor) VALUES(b,own,'owner','active',true,true,true,true);
 INSERT INTO public.business_branches(id,business_id,name,city,address_line,status) VALUES(br,b,'QA Branch','Aden','QA address','pending_review');
 k:='business-verifications/'||b::text||'/'||own||'/'||repeat('a',48)||'.pdf';
 k2:='business-verifications/'||b::text||'/'||own||'/'||repeat('b',48)||'.pdf';
 refs:=jsonb_build_array(k2);
 INSERT INTO public.business_verifications(id,business_id,branch_id,request_type,status,requested_by_user_id,evidence_refs,submitted_at) VALUES(v,b,br,'initial','submitted',own,refs,now());
 INSERT INTO wow_private.verification_submissions(id,verification_id,submitted_by_user_id,evidence_refs,created_at) VALUES(oldsub,v,own,jsonb_build_array(k),now()-interval '1 hour'),(sub,v,own,refs,now());
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',viewer,'role','authenticated')::text,true);
 d:=public.wow_admin_get_business_verification(v);
 IF d->'evidence_refs'<>'[]'::jsonb OR (d->>'evidence_count')::int<>1 OR d::text LIKE '%'||k2||'%' OR d::text LIKE '%'||k||'%' THEN RAISE EXCEPTION 'Viewer evidence disclosure'; END IF;
 INSERT INTO stage5c_cases VALUES('viewer-evidence-redacted');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 d:=public.wow_admin_get_business_verification(v);
 IF d->'evidence_refs'<>'[]'::jsonb THEN RAISE EXCEPTION 'Conflicted evidence disclosed'; END IF;
 BEGIN PERFORM public.wow_admin_decide_business_verification_checked(v,'approved',NULL,sub,refs); RAISE EXCEPTION 'conflicted approval allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO stage5c_cases VALUES('conflicted-verification-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',reviewer,'role','authenticated')::text,true);
 d:=public.wow_admin_get_business_verification(v);
 IF d->'evidence_refs' IS DISTINCT FROM refs THEN RAISE EXCEPTION 'Reviewer evidence missing'; END IF;
 INSERT INTO stage5c_cases VALUES('reviewer-current-evidence');
 BEGIN PERFORM public.wow_admin_decide_business_verification(v,'approved',NULL); RAISE EXCEPTION 'legacy approval bypass'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 INSERT INTO stage5c_cases VALUES('legacy-approval-denied');
 BEGIN PERFORM public.wow_admin_decide_business_verification_checked(v,'approved',NULL,oldsub,refs); RAISE EXCEPTION 'stale submission approved'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 INSERT INTO stage5c_cases VALUES('stale-submission-denied');
 BEGIN PERFORM public.wow_admin_decide_business_verification_checked(v,'approved',NULL,sub,jsonb_build_array(k)); RAISE EXCEPTION 'stale evidence approved'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 INSERT INTO stage5c_cases VALUES('changed-evidence-denied');
 IF public.wow_admin_decide_business_verification_checked(v,'approved',NULL,sub,refs) IS DISTINCT FROM v THEN RAISE EXCEPTION 'checked approval failed'; END IF;
 IF (SELECT status FROM public.businesses WHERE id=b)<>'approved' THEN RAISE EXCEPTION 'approval not persisted'; END IF;
 INSERT INTO stage5c_cases VALUES('exact-submission-approved');
 oldimg:=b::text||'/'||own||'/'||repeat('c',48)||'.jpg'; img:=b::text||'/'||own||'/'||repeat('d',48)||'.jpg';
 UPDATE public.businesses SET logo_url=oldimg WHERE id=b;
 INSERT INTO public.business_profile_revisions(id,business_id,patch,status,requested_by_user_id) VALUES(rev,b,jsonb_build_object('logo_url',img),'submitted',own);
 ctx:=public.wow_admin_get_profile_revision_context(rev);
 IF ctx #>> '{current,logo_url}' IS DISTINCT FROM oldimg OR (ctx->>'media_review_allowed')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'published logo baseline missing'; END IF;
 INSERT INTO stage5c_cases VALUES('reviewer-logo-baseline');
 BEGIN PERFORM public.wow_admin_decide_profile_revision(rev,'approved',NULL); RAISE EXCEPTION 'missing image approved'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 IF (SELECT logo_url FROM public.businesses WHERE id=b) IS DISTINCT FROM oldimg THEN RAISE EXCEPTION 'missing image changed published logo'; END IF;
 INSERT INTO stage5c_cases VALUES('missing-media-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',viewer,'role','authenticated')::text,true);
 ctx:=public.wow_admin_get_profile_revision_context(rev); listing:=public.wow_admin_list_profile_revisions(100,0);
 IF ctx #>> '{current,logo_url}' IS NOT NULL OR (ctx->>'media_review_allowed')::boolean IS DISTINCT FROM false OR listing::text LIKE '%'||img||'%' OR listing::text LIKE '%'||oldimg||'%' THEN RAISE EXCEPTION 'viewer media disclosure'; END IF;
 INSERT INTO stage5c_cases VALUES('viewer-media-redacted');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 ctx:=public.wow_admin_get_profile_revision_context(rev);
 IF (ctx->>'media_review_allowed')::boolean IS DISTINCT FROM false THEN RAISE EXCEPTION 'conflicted media exposed'; END IF;
 BEGIN PERFORM public.wow_admin_decide_profile_revision(rev,'approved',NULL); RAISE EXCEPTION 'conflicted media approved'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO stage5c_cases VALUES('conflicted-media-denied');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',reviewer,'role','authenticated')::text,true);
 IF public.wow_admin_decide_profile_revision(rev,'rejected','Image unavailable for review') IS DISTINCT FROM rev OR (SELECT logo_url FROM public.businesses WHERE id=b) IS DISTINCT FROM oldimg THEN RAISE EXCEPTION 'rejection changed published image'; END IF;
 INSERT INTO stage5c_cases VALUES('rejection-preserves-published-media');
 INSERT INTO public.business_profile_revisions(id,business_id,patch,status,requested_by_user_id) VALUES(rev2,b,jsonb_build_object('logo_url',NULL),'submitted',own);
 IF public.wow_admin_decide_profile_revision(rev2,'approved',NULL) IS DISTINCT FROM rev2 THEN RAISE EXCEPTION 'explicit media removal decision failed'; END IF;
 IF (SELECT logo_url FROM public.businesses WHERE id=b) IS NOT NULL THEN RAISE EXCEPTION 'explicit media removal failed to persist'; END IF;
 INSERT INTO stage5c_cases VALUES('explicit-removal-approved');
 INSERT INTO public.businesses(id,owner_user_id,name,status,approved_at) VALUES(b2,own,'QA business two','approved',now());
 INSERT INTO public.business_members(business_id,user_id,role,status,can_draft,can_submit,can_pause,can_monitor) VALUES(b2,own,'owner','active',true,true,true,true);
 INSERT INTO public.business_profile_revisions(id,business_id,patch,status,requested_by_user_id) VALUES(rev3,b2,jsonb_build_object('cover_url',img),'submitted',own);
 BEGIN PERFORM public.wow_admin_decide_profile_revision(rev3,'approved',NULL); RAISE EXCEPTION 'foreign image accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 INSERT INTO stage5c_cases VALUES('foreign-media-denied');
 IF has_function_privilege('anon','public.wow_admin_decide_business_verification_checked(uuid,text,text,uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'anonymous checked approval granted'; END IF;
 INSERT INTO stage5c_cases VALUES('anon-checked-approval-denied');
END; $test$;
SELECT count(*) AS passed,jsonb_agg(name ORDER BY name) AS cases FROM stage5c_cases;
